import{_ as s,o as l,c as i,ag as e}from"./chunks/framework.DaCm-iTo.js";const p=JSON.parse('{"title":"CoreLib 动作","description":"","frontmatter":{},"headers":[],"relativePath":"modules/skills/corelib-actions.md","filePath":"modules/skills/corelib-actions.md","lastUpdated":null}'),a={name:"modules/skills/corelib-actions.md"};function d(o,t,c,h,n,r){return l(),i("div",null,[...t[0]||(t[0]=[e(`<h1 id="corelib-动作" tabindex="-1">CoreLib 动作 <a class="header-anchor" href="#corelib-动作" aria-label="Permalink to &quot;CoreLib 动作&quot;">​</a></h1><p>EmakiSkills 启用后会向 CoreLib 动作注册表追加技能释放、等级、槽位、冷却和手动解锁段。它们可用于其他模块的奖励、触发器后续效果或 CoreLib 管道模板。</p><blockquote><p>本页只记录 EmakiSkills 注册的段；EmakiSkills 自己的原生技能脚本动作见 <a href="./script.html">原生脚本系统</a>，CoreLib 自带通用段见 <a href="./../corelib/actions.html">CoreLib 动作系统</a>。</p></blockquote><h2 id="段-id-速查" tabindex="-1">段 ID 速查 <a class="header-anchor" href="#段-id-速查" aria-label="Permalink to &quot;段 ID 速查&quot;">​</a></h2><p>十二个段的目标要求都是 <code>REQUIRED_ENTITY</code>。除 <code>cast_skill</code> 与 <code>cast_mythic_skill</code> 外，其余段只接受玩家目标，非玩家目标会跳过。</p><table tabindex="0"><thead><tr><th>段 ID</th><th>用途</th></tr></thead><tbody><tr><td><code>cast_skill</code></td><td>让目标释放一个 EmakiSkills 技能。</td></tr><tr><td><code>cast_mythic_skill</code></td><td>让目标释放一个 MythicMobs 技能。</td></tr><tr><td><code>skill_set_level</code></td><td>直接设置目标指定技能的等级。</td></tr><tr><td><code>skill_upgrade</code></td><td>按升级服务尝试升级目标指定技能。</td></tr><tr><td><code>skill_equip</code></td><td>把技能装备到指定技能槽。</td></tr><tr><td><code>skill_unequip</code></td><td>清空指定技能槽。</td></tr><tr><td><code>skill_bind</code></td><td>给指定技能槽绑定触发器。</td></tr><tr><td><code>skill_cooldown_clear</code></td><td>清除指定技能或全部技能冷却。</td></tr><tr><td><code>skill_cooldown_set</code></td><td>设置指定技能冷却。</td></tr><tr><td><code>skill_learn</code></td><td>通过手动来源解锁技能。</td></tr><tr><td><code>skill_forget</code></td><td>移除一个手动解锁技能。</td></tr><tr><td><code>skill_forget_all</code></td><td>移除全部手动解锁技能。</td></tr></tbody></table><p>旧 id 的对应关系：<code>castskill</code> 与 <code>skill.cast</code> 已不再注册，<code>skill_setlevel</code> 现在写作 <code>skill_set_level</code>，<code>skill_clearcooldown</code> 与 <code>skill_setcooldown</code> 现在写作 <code>skill_cooldown_clear</code> 与 <code>skill_cooldown_set</code>。<code>skill_upgrade</code>、<code>skill_equip</code>、<code>skill_unequip</code>、<code>skill_bind</code>、<code>skill_learn</code>、<code>skill_forget</code>、<code>skill_forget_all</code> 的 id 未变。</p><p>「作用于谁」由 source 决定：作用于执行者自己写 <code>self</code>，指定玩家用 <code>player_by_name</code>。</p><h2 id="cast-skill" tabindex="-1">cast_skill <a class="header-anchor" href="#cast-skill" aria-label="Permalink to &quot;cast_skill&quot;">​</a></h2><p>让目标作为施法者释放一个 EmakiSkills 技能。</p><blockquote><p><strong>破坏性变更。</strong> <code>skill</code> 参数接受的是 <strong>EmakiSkills 技能 id</strong>，不再是 MythicMobs 技能 id。原先在这里写 MythicMobs 技能名的配置必须改用 <code>cast_mythic_skill</code>。</p></blockquote><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>必填</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>skill</code></td><td>STRING</td><td>是</td><td>—</td><td>EmakiSkills 技能 id。</td></tr><tr><td><code>bypass_cooldown</code></td><td>BOOLEAN</td><td>否</td><td><code>false</code></td><td>跳过该技能自身冷却与全局冷却检查。</td></tr><tr><td><code>bypass_resource_check</code></td><td>BOOLEAN</td><td>否</td><td><code>false</code></td><td>资源不足时也照样施放。</td></tr><tr><td><code>consume_resource</code></td><td>BOOLEAN</td><td>否</td><td><code>true</code></td><td>施放成功后是否扣除资源消耗。</td></tr></tbody></table><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | cast_skill skill=fireball&#39;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # 管理员测试：不吃冷却、不扣资源</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | cast_skill skill=fireball bypass_cooldown=true consume_resource=false&#39;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # 免费施放一次，即使资源不够</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | cast_skill skill=heal bypass_resource_check=true consume_resource=false&#39;</span></span></code></pre></div><p>这个段走 EmakiSkills 自己的施法流程，所以冷却、资源消耗、施放条件与前后置施法事件都会生效。</p><h3 id="玩家与非玩家施法者" tabindex="-1">玩家与非玩家施法者 <a class="header-anchor" href="#玩家与非玩家施法者" aria-label="Permalink to &quot;玩家与非玩家施法者&quot;">​</a></h3><p>两条路径的行为不同，因为技能档案只对玩家存在：</p><ul><li><strong>玩家施法者</strong>：完整施法流程，上面三个开关全部有效。</li><li><strong>其他实体施法者</strong>：只施放该技能的 <code>mythicSkill</code> 部分。实体没有技能档案，既没有冷却可读也没有资源池可扣，所以三个开关在这条路径上无效；纯脚本技能（没有配置 <code>mythicSkill</code>）会被拒绝而不是静默什么都不做。</li></ul><h3 id="结果判定" tabindex="-1">结果判定 <a class="header-anchor" href="#结果判定" aria-label="Permalink to &quot;结果判定&quot;">​</a></h3><p>施法流程是异步的，而段必须同步给出结果，所以它检查一次已完成状态而不等待：调用返回时已经失败的施放是在同步关卡上被拦下的（冷却、资源、激活类型不符），这是管道可以据此分支的结果；仍在进行中的施放报告为成功，后续失败只写入 debug 日志。这与 <code>start_task</code> 的取舍一致：段保证的是这次施放已被接受，不是它已经完成。</p><p><code>skill</code> 为空、技能 id 不存在都会以 <code>INVALID_CONFIG</code> 失败。</p><h2 id="cast-mythic-skill" tabindex="-1">cast_mythic_skill <a class="header-anchor" href="#cast-mythic-skill" aria-label="Permalink to &quot;cast_mythic_skill&quot;">​</a></h2><p>让目标释放一个 MythicMobs 技能。这个段本轮从 CoreLib 迁到 EmakiSkills，注册分类是 <code>integration</code>。</p><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>必填</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>skill</code></td><td>STRING</td><td>是</td><td>—</td><td>MythicMobs 技能 id。</td></tr></tbody></table><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | cast_mythic_skill skill=FireballSkill&#39;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # 让准星上的实体释放</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;looking_at range=20 | cast_mythic_skill skill=ExplodeSkill&#39;</span></span></code></pre></div><p>任何实体都可以作为施法者，这也是这个段与 <code>cast_skill</code> 分开的理由。MythicMobs 是可选依赖：未安装或桥接初始化失败时该段以 <code>OWNER_DISABLED</code> 失败，不会把管道带下去。<code>skill</code> 值不做 id 归一化，按 MythicMobs 的原样写法传入。</p><h2 id="技能等级" tabindex="-1">技能等级 <a class="header-anchor" href="#技能等级" aria-label="Permalink to &quot;技能等级&quot;">​</a></h2><h3 id="skill-set-level" tabindex="-1">skill_set_level <a class="header-anchor" href="#skill-set-level" aria-label="Permalink to &quot;skill_set_level&quot;">​</a></h3><p>直接写入等级，不检查升级材料也不摇成功率。</p><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>必填</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>skill</code></td><td>STRING</td><td>是</td><td>—</td><td>技能 id。</td></tr><tr><td><code>level</code></td><td>INTEGER</td><td>是</td><td>—</td><td>目标等级。</td></tr></tbody></table><h3 id="skill-upgrade" tabindex="-1">skill_upgrade <a class="header-anchor" href="#skill-upgrade" aria-label="Permalink to &quot;skill_upgrade&quot;">​</a></h3><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>必填</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>skill</code></td><td>STRING</td><td>是</td><td>—</td><td>技能 id。</td></tr></tbody></table><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | skill_set_level skill=fireball level=3&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | skill_upgrade skill=fireball&#39;</span></span></code></pre></div><p><code>skill_upgrade</code> 会走 EmakiSkills 的升级服务，因此仍会检查升级材料、经济、成功率并执行升级动作。技能 id 不存在时以 <code>INVALID_CONFIG</code> 失败。</p><h2 id="技能槽" tabindex="-1">技能槽 <a class="header-anchor" href="#技能槽" aria-label="Permalink to &quot;技能槽&quot;">​</a></h2><table tabindex="0"><thead><tr><th>段 ID</th><th>参数</th><th>说明</th></tr></thead><tbody><tr><td><code>skill_equip</code></td><td><code>slot</code>（INTEGER，必填）、<code>skill</code>（STRING，必填）</td><td>将技能装备到指定槽位。</td></tr><tr><td><code>skill_unequip</code></td><td><code>slot</code>（INTEGER，必填）</td><td>清空指定槽位。</td></tr><tr><td><code>skill_bind</code></td><td><code>slot</code>（INTEGER，必填）、<code>trigger</code>（STRING，必填）</td><td>将触发器绑定到指定槽位。</td></tr></tbody></table><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | skill_equip slot=0 skill=fireball&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | skill_bind slot=0 trigger=right_click&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | skill_unequip slot=0&#39;</span></span></code></pre></div><p>槽位校验全部在 <code>PlayerSkillStateService</code> 内完成：它掌握已解锁技能集合、触发器冲突表和槽位变更事件。<code>slot</code> 读不出来时按 <code>-1</code> 处理，会被状态服务拒绝，所以写错的值会明确失败而不是打到 0 号槽。</p><h2 id="冷却" tabindex="-1">冷却 <a class="header-anchor" href="#冷却" aria-label="Permalink to &quot;冷却&quot;">​</a></h2><h3 id="skill-cooldown-clear" tabindex="-1">skill_cooldown_clear <a class="header-anchor" href="#skill-cooldown-clear" aria-label="Permalink to &quot;skill_cooldown_clear&quot;">​</a></h3><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>必填</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>skill</code></td><td>STRING</td><td>否</td><td><code>&quot;&quot;</code></td><td>技能 id；为空时清除全部冷却与施法延迟。</td></tr></tbody></table><h3 id="skill-cooldown-set" tabindex="-1">skill_cooldown_set <a class="header-anchor" href="#skill-cooldown-set" aria-label="Permalink to &quot;skill_cooldown_set&quot;">​</a></h3><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>必填</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>skill</code></td><td>STRING</td><td>是</td><td>—</td><td>技能 id。</td></tr><tr><td><code>duration_ticks</code></td><td>TIME</td><td>是</td><td>—</td><td>冷却时间；小于等于 0 时等效于清除该技能冷却。</td></tr></tbody></table><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | skill_cooldown_set skill=fireball duration_ticks=5s&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | skill_cooldown_clear skill=fireball&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | skill_cooldown_clear&#39;</span></span></code></pre></div><h2 id="手动解锁" tabindex="-1">手动解锁 <a class="header-anchor" href="#手动解锁" aria-label="Permalink to &quot;手动解锁&quot;">​</a></h2><p>手动解锁来源会写入玩家技能档案，GUI 中会显示为「手动解锁」。遗忘技能后，EmakiSkills 会校验并清理无效槽位绑定。</p><table tabindex="0"><thead><tr><th>段 ID</th><th>参数</th><th>说明</th></tr></thead><tbody><tr><td><code>skill_learn</code></td><td><code>skill</code>（STRING，必填）</td><td>将技能加入玩家的手动解锁来源。</td></tr><tr><td><code>skill_forget</code></td><td><code>skill</code>（STRING，必填）</td><td>移除一个手动解锁技能。</td></tr><tr><td><code>skill_forget_all</code></td><td>无</td><td>移除全部手动解锁技能。</td></tr></tbody></table><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | skill_learn skill=fireball&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | skill_forget skill=fireball&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | skill_forget_all&#39;</span></span></code></pre></div><p>这三个段只处理手动来源。装备或其他来源授予的技能在别处收集，无法通过它们遗忘。</p><p><code>skill_learn</code> 对一个已解锁的技能按跳过处理而不是失败：管道的意图已经达成了。</p><h2 id="使用提示" tabindex="-1">使用提示 <a class="header-anchor" href="#使用提示" aria-label="Permalink to &quot;使用提示&quot;">​</a></h2><ul><li><code>cast_skill</code> 与 <code>cast_mythic_skill</code> 接受任意实体作为施法者，其余十个段只接受玩家目标。</li><li><code>cast_mythic_skill</code> 需要 MythicMobs 已安装并启用，且 <code>skill</code> 指向的技能存在。</li><li>技能 id 在传入前会做归一化（大小写与分隔符），MythicMobs 技能 id 不做归一化。</li><li>相关服务尚未就绪时，段以 <code>MISSING_CONTEXT</code> 失败而不是静默跳过。</li></ul>`,51)])])}const b=s(a,[["render",d]]);export{p as __pageData,b as default};
